Export these functions for tests:

```javascript
export function classifySignalStatus(signal) { ... }
export function classifyCoverage({ latest, sourceStatus, ageHours, staleAfterHours, missingInputCount }) { ... }
export function makeCycleStatusNote(input) { ... }
export async function pull(flags = {}) { ... }
```

Use this coverage behavior:

```javascript
if (!latest) return { coverageStatus: 'gap', cycleState: 'data_gap' };
if (sourceStatus === 'degraded') return { coverageStatus: 'degraded', cycleState: 'degraded' };
if (ageHours > staleAfterHours) return { coverageStatus: 'stale', cycleState: 'data_gap' };
if (missingInputCount > 0) return { coverageStatus: 'partial', cycleState: signalStatus === 'alert' || signalStatus === 'critical' ? 'stress' : signalStatus === 'watch' ? 'watch' : 'incomplete' };
return { coverageStatus: 'active', cycleState: signalStatus === 'alert' || signalStatus === 'critical' ? 'stress' : signalStatus === 'watch' ? 'watch' : 'stable' };
```

